detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — minimize total cost (fixed setup costs plus variable production costs), maximize profit (with selling prices given), or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the market demand for each container type a minimum that must be met (i.e., you must produce at least the listed demand), or is it a maximum you may not exceed, or an exact target you must hit precisely?"
  ],
  "rationale": "The response asks for a single policy choice regarding the nature of the demand constraint (minimum, maximum, or exact), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a larger container type is used to satisfy the demand of a smaller type, does the larger container's own demand still have to be met separately (i.e., substitution is an additional source on top of each type's own demand), or does using a larger container to cover a smaller type's demand reduce what that larger type must produce for its own demand?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy choice regarding how substitution affects the demand of the larger container type."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a larger container type is used to satisfy a smaller type's demand, is the variable production cost charged at the larger container's own unit cost (e.g., 18 Yuan for type 6), or is it charged at the smaller demand type's unit cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding cost allocation, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any upper limit on how many units of a larger container type can be produced beyond its own demand (i.e., a capacity ceiling on total production per type), or can a type produce any non-negative quantity as long as its demand is covered?"
  ],
  "rationale": "The response asks a single clarification question regarding production capacity limits, presenting two mutually exclusive options for the user to choose from."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a container type be used to satisfy the demand of another type with the same volume code (i.e., can type 3 be used to cover type 3's own demand as a \"substitution\"), or is substitution strictly from a strictly larger type to a strictly smaller type, with each type's own demand always covered by its own production?"
  ],
  "rationale": "The response asks for a single policy decision regarding the definition of substitution rules (self-coverage vs. strict size hierarchy), which constitutes one independent question."
}

